import numpy as np, pandas as pd, sys
from lmfit.models import LorentzianModel, LinearModel
for f in ["spectrum_spot1.csv","spectrum_spot2.csv"]:
    d=pd.read_csv(f); m=(d.shift_cm1>320)&(d.shift_cm1<445)
    x=d.shift_cm1[m].values; y=d.intensity[m].values
    for n,cs in [(1,[352]),(2,[350,355])]:
        mod=LinearModel(prefix='b_'); pars=mod.make_params(b_slope=0,b_intercept=np.median(y[:10]))
        for i,c in enumerate(cs):
            l=LorentzianModel(prefix=f'p{i}_'); pars.update(l.make_params(p{i}_center=c,p{i}_sigma=4,p{i}_amplitude=10000) if False else l.make_params(center=c,sigma=4,amplitude=10000)) if False else None
        mod=LinearModel(prefix='b_'); pars=mod.make_params(slope=0,intercept=np.median(y[:10]))
        for i,c in enumerate(cs+[418]):
            l=LorentzianModel(prefix=f'p{i}_'); mod=mod+l
            pars.update(l.make_params(center=c,sigma=3,amplitude=10000))
        r=mod.fit(y,pars,x=x)
        print(f,n,'chi2red',round(r.redchi,1),'bic',round(r.bic,1))
        for k in r.params:
            if k.endswith('center') or k.endswith('fwhm') or k.endswith('height'): print('  ',k,round(r.params[k].value,2),'+-',round(r.params[k].stderr or 0,2))
